	var item = pool.getRandomItemTopHeavy(0)
	value -= item.getPrice()

	ItemBook.generateAndStorageItem(item, global_position)

if not stable:
	inventory.removeItem(self)
	discard()
else:
	activate()

Game.saveRunState()

if validBonds.size() >= 8:
	SteamHelper.unlockAchievement("Recombobulator")

