methods._process:
def _process(_item, _delta=None):
    previousSocket = None; sockets = None; s = None; closestSocket = None; closestDist = None; dist = None
    if _item.dragged:

        if _item.draggedInsideItems:
            return

        previousSocket = _item.hoveredSocket

        sockets = []
        for area in _range_or_value(_item.socketDetectionArea.get_overlapping_areas()):
            s = area.get_parent()
            if s.item.visible:
                pass  # visual

        if (not sockets):
            _item.hoveredSocket = None
            if previousSocket == None:
                _item.affectedCellsActive = True
        else:
            closestSocket = None
            closestDist = INF
            for s in _range_or_value(sockets):
                if s.isAvailable():
                    dist = (s.global_position - global_position).length_squared()
                    if dist < closestDist:
                        closestSocket = s
                        closestDist = dist

            if closestSocket:
                _item.hoveredSocket = closestSocket
                _item.affectedCellsActive = False

        if _item.hoveredSocket != previousSocket:
            if previousSocket != None:
                previousSocket.onHoverEndWithGem()

            if _item.hoveredSocket != None:
                _item.hoveredSocket.onHoverWithGem()

