methods.getSizeInCells:
def getSizeInCells(_item):
    topLeft = None; bottomRight = None; cells = None
    topLeft = Vector2(100, 100)
    bottomRight = Vector2( - 100, - 100)
    cells = _item._behavior_call("getCollisionCells", )
    if (not cells):
        return Vector2.ZERO

    for cell in _range_or_value(cells):
        if cell.x < topLeft.x:
            topLeft.x = cell.x
        if cell.y < topLeft.y:
            topLeft.y = cell.y

        if cell.x > bottomRight.x:
            bottomRight.x = cell.x
        if cell.y > bottomRight.y:
            bottomRight.y = cell.y

    return bottomRight - topLeft + Vector2(1, 1)

