methods.pickRandomStacks:
def pickRandomStacks(_item, stackTypes=None, numStacks=None, target=None, priorityStack=None):
    stacks = None; numTargetStacks = None; pickedStacks = None; pickedPriorityStacks = None; stackType = None
    stacks = Dictionary()
    for stackType in _range_or_value(stackTypes):
        numTargetStacks = target.get_stacks(stackType)
        if numTargetStacks > 0:
            stacks[stackType] = numTargetStacks

    pickedStacks = Dictionary()

    if priorityStack != None:
        pickedPriorityStacks = min(numStacks, stacks.get(priorityStack, 0))
        if pickedPriorityStacks > 0:
            pickedStacks[priorityStack] = pickedPriorityStacks
            numStacks -= pickedPriorityStacks
            pass  # visual

    for i in _range_or_value(numStacks):
        if stacks:
            stackType = Util.pickRandomElement(stacks.keys())
            Util.dictAdd(pickedStacks, stackType, 1)
            pass  # visual

    return pickedStacks

