methods.getLeastStacks:
def getLeastStacks(_item, numStacks=None, target=None, availableStacks=None):
    priorStacks = None; pickedStacks = None; leastStacksCount = None; leastStacks = None; stackToGive = None
    priorStacks = {}
    for stackType in _range_or_value(availableStacks):
        priorStacks[stackType] = target.get_stacks(stackType)

    pickedStacks = {}


    while numStacks > 0:
        leastStacksCount = 10000
        leastStacks = []
        for stackType in _range_or_value(priorStacks):
            if priorStacks[stackType] < leastStacksCount:
                leastStacksCount = priorStacks[stackType]
                leastStacks.clear()
                leastStacks.append(stackType)
            elif priorStacks[stackType] == leastStacksCount:
                leastStacks.append(stackType)
        stackToGive = Util.pickRandomElement(leastStacks)
        Util.dictAdd(pickedStacks, stackToGive, 1)
        Util.dictAdd(priorStacks, stackToGive, 1)
        numStacks -= 1

    return pickedStacks

