def considerAsBond(_item, neighbor=None):
    score = None; recipe = None; progressBefore = None; progressWithNeighbor = None; bestScore = None; s = None
    score = 0.0
    recipe = None
    if _item.curRecipe:
        if _item._behavior_call("isRecipeFinished", ):
            return None

        if _item.curRecipe.checkNeighbor(_item.bondedIngredients, neighbor):
            progressBefore = _item.curRecipe.getProgress(_item.bondedIngredients)
            progressWithNeighbor = (len(_item.bondedIngredients) + 1) / float(_item.curRecipe.getNumIngredients())
            pass  # visual
            recipe = _item.curRecipe
    else:
        bestScore = 0.0
        for r in _range_or_value(_item._behavior_call("getRecipes", )):
            if r.checkNeighbor([], neighbor):
                s = 1.0 / r.getNumIngredients()
                if s > bestScore:
                    bestScore = s
                    recipe = r

        score = bestScore

    if recipe:
        return [recipe, score]
    else:
        return None

