def onDamaged(_item, _damage=None, event=None):
    heat = None; event2 = None
    if _item.deathPrevented:
        return

    if _item.character_().get_current_health() <= 0:
        heat = _item.character_().get_heat()
        if heat > 0:
            _item.setState(True)

            event2 = _item.character_().reincarnate(_item.reincarnateHealth * heat, False, _item, event)
            _item.use_heat(heat, event2)
            _item.visual_activate()
            pass  # visual

methods.doCooldownEffect:
def doCooldownEffect(_item):
    res = None
    if _item.use_stamina() == Character.StaminaResult.Sufficient:
        if _item.character_().get_current_health() > _item.selfDam:
            _item.character_().lose_health(_item.selfDam, _item)
            res = _item.deal_damage()
