methods.onBuffsChanged:
def onBuffsChanged(_item, amount=None, event=None):
    ticks = None
    if event.get_origin() in _item.affectedItemsDict:
        if amount > 0:
            _item.gainedBuffs += amount
            ticks = _item.gainedBuffs / _item.gainedThreshold
            if ticks > 0:
                _item._behavior_call("onGainThresholdReached", ticks, event)
                _item.gainedBuffs %= _item.gainedThreshold
        else:

            _item.usedBuffs += int(abs(amount))
            ticks = _item.usedBuffs / _item.usedThreshold
            if ticks > 0:
                _item._behavior_call("onUseThresholdReached", ticks, event)
                _item.usedBuffs %= _item.usedThreshold

